sys_script_include.script:
var refund_details = Class.create();
refund_details.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getOrderInfo: function(){
		var gr = new GlideRecord('x_1771422_refund_0_order_details');
		gr.addQuery('sys_id', this.getParameter('sysparm_orderId'));

		gr.query();
		var orderdetails = {};
		if(gr.next()){

			orderdetails.full_name = gr.full_name + '';
			orderdetails.email = gr.email + '';
			orderdetails.contact_number = gr.contact_number + '';
			orderdetails.district = gr.district + '';
			orderdetails.street_line_2 = gr.street_line_2 + '';
			orderdetails.door_no_street_line_1 = gr.door_no_street_line_1 + '';
			orderdetails.street_line_3 = gr.street_line_3 + '';
			orderdetails.city = gr.city + '';
			orderdetails.pincode = gr.pincode + '';
            orderdetails.state = gr.state + '';
			orderdetails.date_of_purchase = gr.date_of_purchase + '';
		}
		gs.info(orderdetails);
		return JSON.stringify(orderdetails);
	},
    type: 'refund_details'
});
